//! 🧊️ Irregular three-dimensional slots, typed media and named constraint channels.
use crate::standards::v1::subsets::any::schema::snapshot::{Wfc3dSnapshot,Tile,TileMedia3d,Color,Slot3d,SlotEdge,GraphRule};
use semio_framework_os_kernel::{ArtifactSqliteSnapshot,sqlite_snapshot::{SqliteDatabase,SqliteValue,SqliteSnapshotControl,SqliteSnapshotPhase,SnapshotEncoding,validate_sqlite_database_schema,artifact::{Cell,RowWriter,Reconstruction,NativeEncodingBound,FloatColumn,FloatRow}}};
use std::collections::{BTreeMap,BTreeSet};
use semio_framework_value::ValueError;
fn invalid(message:impl Into<String>)->ValueError{ValueError::new(semio_framework_value::ValueRefusalKind::InvalidValue,message)}
fn index(n:usize)->Result<i64,ValueError>{i64::try_from(n).map_err(|_|semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::WorkLimit,"wfc3d ordinal overflow"))}
fn floats(t:&str)->&'static[FloatColumn]{match t{"wfc3d_tile"=>&[FloatColumn::Binary64(5)],"wfc3d_position"=>&[FloatColumn::Binary64(3)],"wfc3d_slot"=>&[FloatColumn::Binary64(4),FloatColumn::Binary64(5),FloatColumn::Binary64(6),FloatColumn::Binary64(7),FloatColumn::Binary64(8),FloatColumn::Binary64(9)],_=>&[]}}
fn identity(r:FloatRow<'_>,n:usize)->Result<(),ValueError>{if r.rowid<=0||r.integer(0)?!=r.rowid||r.values.len()!=n{return Err(invalid("wfc3d entity identity or columns differ"))}Ok(())}
fn word(r:FloatRow<'_>,i:usize)->Result<u32,ValueError>{u32::try_from(r.integer(i)?).map_err(|_|invalid("wfc3d unsigned32 differs"))}
fn byte(r:FloatRow<'_>,i:usize)->Result<u8,ValueError>{u8::try_from(r.integer(i)?).map_err(|_|invalid("wfc3d unsigned8 color differs"))}
fn flag(r:FloatRow<'_>,i:usize)->Result<bool,ValueError>{match r.integer(i)?{0=>Ok(false),1=>Ok(true),_=>Err(invalid("wfc3d boolean differs"))}}
fn rows<'a>(d:&'a SqliteDatabase,t:&str,c:&mut SqliteSnapshotControl<'_>)->Result<Vec<FloatRow<'a>>,ValueError>{let mut result=Vec::new();let mut seen=BTreeSet::new();for(i,r)in d.table(t)?.rows.iter().enumerate(){if i%256==0{c.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,i,0)?;}let r=FloatRow::new(r,floats(t))?;if !seen.insert(r.rowid){return Err(invalid("duplicate wfc3d entity identity"))}result.push(r);}Ok(result)}
fn ordered<'a>(mut rows:Vec<FloatRow<'a>>)->Result<Vec<FloatRow<'a>>,ValueError>{rows.sort_by_key(|r|r.integer(2).unwrap_or(-1));for(i,r)in rows.iter().enumerate(){if r.integer(2)?!=index(i)?{return Err(invalid("wfc3d ordinals must be contiguous"))}}Ok(rows)}
fn groups<'a>(d:&'a SqliteDatabase,t:&str,n:usize,owners:&BTreeSet<i64>,c:&mut SqliteSnapshotControl<'_>)->Result<BTreeMap<i64,Vec<FloatRow<'a>>>,ValueError>{let mut map=BTreeMap::<i64,Vec<FloatRow<'a>>>::new();for(i,r)in rows(d,t,c)?.into_iter().enumerate(){identity(r,n)?;let owner=r.integer(1)?;if !owners.contains(&owner){return Err(invalid("wfc3d relationship has an unknown owner"))}map.entry(owner).or_default().push(r);if i%256==0{c.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,i,0)?;}}Ok(map)}
fn decimal(mut value:u64,buffer:&mut[u8;20])->&str{let mut start=buffer.len();loop{start-=1;buffer[start]=b'0'+(value%10)as u8;value/=10;if value==0{break;}}std::str::from_utf8(&buffer[start..]).expect("decimal digits are ASCII")}
impl Wfc3dSnapshot{
 pub(crate) fn admit_sqlite_values(&self,c:&mut SqliteSnapshotControl<'_>,phase:SqliteSnapshotPhase)->Result<(),ValueError>{let mut p=RowWriter::borrowed(c,phase)?;self.write_sqlite_rows(&mut p)?;p.finish_borrowed()}
 fn write_sqlite_rows(&self,p:&mut RowWriter<'_,'_>)->Result<(),ValueError>{let mut seed=[0;20];
 p.insert_key("wfc3d_document",1,&[Cell::Text(&self.schema),Cell::Text(decimal(self.seed,&mut seed))])?;
 for(i,t)in self.tiles.iter().enumerate(){let kind=match &t.media{TileMedia3d::Mesh{..}=>"mesh",TileMedia3d::MeshChild{..}=>"mesh_child"};let id=p.insert_float("wfc3d_tile",&[Cell::Integer(1),Cell::Integer(index(i)?),Cell::Text(&t.id),t.label.as_deref().map_or(Cell::Null,Cell::Text),Cell::Real(t.weight),Cell::Text(kind)],floats("wfc3d_tile"))?;match &t.media{TileMedia3d::Mesh{positions,indices,color}=>{p.insert_key("wfc3d_mesh",id,&[])?;for(i,v)in positions.iter().enumerate(){p.insert_float("wfc3d_position",&[Cell::Integer(id),Cell::Integer(index(i)?),Cell::Real(*v)],floats("wfc3d_position"))?;}for(i,v)in indices.iter().enumerate(){p.insert("wfc3d_index",&[Cell::Integer(id),Cell::Integer(index(i)?),Cell::Integer(i64::from(*v))])?;}if let Some(c)=color{p.insert_key("wfc3d_color",id,&[Cell::Integer(i64::from(c.r)),Cell::Integer(i64::from(c.g)),Cell::Integer(i64::from(c.b)),Cell::Integer(i64::from(c.a))])?;}},TileMedia3d::MeshChild{child}=>{let target=&child.target;p.insert_key("wfc3d_mesh_child",id,&[Cell::Text(&child.child_id),Cell::Text(&target.artifact_id),Cell::Text(&target.dialect.artifact_kind),Cell::Text(&target.dialect.standard),Cell::Text(&target.dialect.subset)])?;}}}
 for(i,s)in self.slots.iter().enumerate(){let pin=match &s.pinned_tile_id{None=>Cell::Null,Some(name)=>Cell::Text(name)};p.insert_float("wfc3d_slot",&[Cell::Integer(1),Cell::Integer(index(i)?),Cell::Text(&s.id),Cell::Real(s.x),Cell::Real(s.y),Cell::Real(s.z),Cell::Real(s.width),Cell::Real(s.height),Cell::Real(s.depth),pin],floats("wfc3d_slot"))?;}
 for(i,e)in self.edges.iter().enumerate(){p.insert("wfc3d_slot_edge",&[Cell::Integer(1),Cell::Integer(index(i)?),Cell::Text(&e.id),Cell::Text(&e.from_slot_id),Cell::Text(&e.to_slot_id),Cell::Text(&e.relation)])?;}
 for(i,r)in self.rules.iter().enumerate(){p.insert("wfc3d_rule",&[Cell::Integer(1),Cell::Integer(index(i)?),Cell::Text(&r.id),Cell::Text(&r.tile_a_id),Cell::Text(&r.tile_b_id),r.relation.as_deref().map_or(Cell::Null,Cell::Text),Cell::Integer(i64::from(r.allowed))])?;}
 Ok(())
 }
}
impl ArtifactSqliteSnapshot for Wfc3dSnapshot{
const SQLITE_SCHEMA:&'static str=include_str!("🗄️.sql");
fn decode_sqlite_snapshot_native(payload:&store::io_schema::IoPayload,c:&mut SqliteSnapshotControl<'_>)->Result<Self,ValueError>{crate::standards::v1::subsets::any::io::text::snapshot::decode_sqlite_snapshot_native(payload,c)}
fn encode_sqlite_snapshot_native(&self,encoding:SnapshotEncoding,c:&mut SqliteSnapshotControl<'_>)->Result<store::io_schema::IoPayload,ValueError>{crate::standards::v1::subsets::any::io::text::snapshot::encode_sqlite_snapshot_native(self,encoding,c)}
fn to_sqlite_database(&self,c:&mut SqliteSnapshotControl<'_>)->Result<SqliteDatabase,ValueError>{let mut p=RowWriter::new(Self::SQLITE_SCHEMA,c)?;self.write_sqlite_rows(&mut p)?;p.finish()}
fn from_sqlite_database(d:&SqliteDatabase,c:&mut SqliteSnapshotControl<'_>)->Result<Self,ValueError>{
 validate_sqlite_database_schema(d,Self::SQLITE_SCHEMA,c.limits())?;c.check_database(d,SqliteSnapshotPhase::ReconstructSnapshot)?;let doc=FloatRow::new(d.table("wfc3d_document")?.single_row()?,&[])?;identity(doc,3)?;if doc.rowid!=1{return Err(invalid("wfc3d root identity must be one"))}let seed=doc.text(2)?.parse::<u64>().map_err(|_|invalid("wfc3d seed exceeds unsigned64"))?;if seed.to_string()!=doc.text(2)?{return Err(invalid("wfc3d seed requires canonical decimal"))}
 let root=BTreeSet::from([1]);let tile_rows=ordered(groups(d,"wfc3d_tile",7,&root,c)?.remove(&1).unwrap_or_default())?;let mut mesh_ids=BTreeSet::new();let mut child_ids=BTreeSet::new();for(i,r)in tile_rows.iter().enumerate(){r.text(3)?;match r.text(6)?{"mesh"=>{mesh_ids.insert(r.rowid);},"mesh_child"=>{child_ids.insert(r.rowid);},_=>return Err(invalid("wfc3d media kind differs"))}if i%256==0{c.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,i,0)?;}}
 let mut seen=BTreeSet::new();for(i,r)in rows(d,"wfc3d_mesh",c)?.into_iter().enumerate(){identity(r,1)?;if !mesh_ids.contains(&r.rowid){return Err(invalid("wfc3d mesh has unknown or wrong-kind owner"))}seen.insert(r.rowid);if i%256==0{c.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,i,0)?;}}if seen!=mesh_ids{return Err(invalid("wfc3d mesh ownership is incomplete"))}
 let mut positions=groups(d,"wfc3d_position",4,&mesh_ids,c)?;let mut indices=groups(d,"wfc3d_index",4,&mesh_ids,c)?;let mut colors=BTreeMap::new();for(i,r)in rows(d,"wfc3d_color",c)?.into_iter().enumerate(){identity(r,5)?;if !mesh_ids.contains(&r.rowid){return Err(invalid("wfc3d color has unknown mesh"))}colors.insert(r.rowid,r);if i%256==0{c.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,i,0)?;}}
 let mut children=BTreeMap::new();for(i,r)in rows(d,"wfc3d_mesh_child",c)?.into_iter().enumerate(){identity(r,6)?;if !child_ids.contains(&r.rowid){return Err(invalid("wfc3d child has wrong-kind or unknown owner"))}children.insert(r.rowid,r);if i%256==0{c.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,i,0)?;}}if children.len()!=child_ids.len(){return Err(invalid("wfc3d child ownership is incomplete"))}
 let slot_rows=ordered(groups(d,"wfc3d_slot",11,&root,c)?.remove(&1).unwrap_or_default())?;for(i,r)in slot_rows.iter().enumerate(){r.text(3)?;if i%256==0{c.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,i,0)?;}}
 let edge_rows=ordered(groups(d,"wfc3d_slot_edge",7,&root,c)?.remove(&1).unwrap_or_default())?;let rule_rows=ordered(groups(d,"wfc3d_rule",8,&root,c)?.remove(&1).unwrap_or_default())?;
 let mut owned=Reconstruction::new(c)?;let schema=owned.text(doc.text(1)?)?;owned.scalar()?;let mut tiles=Vec::new();for r in tile_rows{owned.scalar()?;let media=if mesh_ids.contains(&r.rowid){let mut native_positions=Vec::new();for v in ordered(positions.remove(&r.rowid).unwrap_or_default())?{owned.scalar()?;native_positions.push(v.real(3)?);}let mut native_indices=Vec::new();for v in ordered(indices.remove(&r.rowid).unwrap_or_default())?{owned.scalar()?;native_indices.push(word(v,3)?);}let color=match colors.remove(&r.rowid){None=>None,Some(v)=>{for _ in 0..4{owned.scalar()?;}Some(Color{r:byte(v,1)?,g:byte(v,2)?,b:byte(v,3)?,a:byte(v,4)?})}};TileMedia3d::Mesh{positions:native_positions,indices:native_indices,color}}else{let v=children.remove(&r.rowid).ok_or_else(||invalid("wfc3d child absent"))?;let target=semio_framework_artifact_reference::ArtifactRef{artifact_id:owned.text(v.text(2)?)?,dialect:semio_framework_artifact_reference::ArtifactDialect{artifact_kind:owned.text(v.text(3)?)?,standard:owned.text(v.text(4)?)?,subset:owned.text(v.text(5)?)?}};TileMedia3d::MeshChild{child:store::ArtifactChild::new(owned.text(v.text(1)?)?,target)}};tiles.push(Tile{id:owned.text(r.text(3)?)?,label:r.optional_text(4)?.map(|s|owned.text(s)).transpose()?,weight:r.real(5)?,media});}
 let mut slots=Vec::new();for r in slot_rows{for _ in 0..6{owned.scalar()?;}let pin=match r.values[10]{SqliteValue::Null=>None,_=>Some(owned.text(r.text(10)?)?)};slots.push(Slot3d{id:owned.text(r.text(3)?)?,x:r.real(4)?,y:r.real(5)?,z:r.real(6)?,width:r.real(7)?,height:r.real(8)?,depth:r.real(9)?,pinned_tile_id:pin});}
 let mut edges=Vec::new();for r in edge_rows{edges.push(SlotEdge{id:owned.text(r.text(3)?)?,from_slot_id:owned.text(r.text(4)?)?,to_slot_id:owned.text(r.text(5)?)?,relation:owned.text(r.text(6)?)?});owned.checkpoint()?;}
 let mut rules=Vec::new();for r in rule_rows{owned.scalar()?;rules.push(GraphRule{id:owned.text(r.text(3)?)?,tile_a_id:owned.text(r.text(4)?)?,tile_b_id:owned.text(r.text(5)?)?,relation:r.optional_text(6)?.map(|s|owned.text(s)).transpose()?,allowed:flag(r,7)?});}owned.checkpoint()?;Ok(Self{schema,seed,tiles,slots,edges,rules})
}
fn preflight_sqlite_snapshot_encoding(&self,_encoding:SnapshotEncoding,c:&mut SqliteSnapshotControl<'_>)->Result<(),ValueError>{let mut b=NativeEncodingBound::new(c)?;b.add(4096)?;b.repeated(self.schema.len(),16)?;let mut total=1usize;for n in [self.slots.len(),self.edges.len(),self.tiles.len(),self.rules.len()]{total=total.checked_add(n).ok_or_else(||semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::WorkLimit,"wfc3d native entity overflow"))?;b.check_rows(total)?;}for t in &self.tiles{b.repeated(t.id.len(),16)?;if let Some(v)=&t.label{b.repeated(v.len(),16)?;}b.add(4096)?;match &t.media{TileMedia3d::Mesh{positions,indices,color}=>{total=total.checked_add(positions.len()).and_then(|n|n.checked_add(indices.len())).ok_or_else(||semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::WorkLimit,"wfc3d native mesh count overflow"))?;b.check_rows(total)?;b.repeated(positions.len(),2048)?;b.repeated(indices.len(),256)?;if color.is_some(){b.add(1024)?;}},TileMedia3d::MeshChild{child}=>{let target=&child.target;for v in [&child.child_id,&target.artifact_id,&target.dialect.artifact_kind,&target.dialect.standard,&target.dialect.subset]{b.repeated(v.len(),16)?;}}}}for s in &self.slots{b.repeated(s.id.len(),16)?;if let Some(v)=&s.pinned_tile_id{b.repeated(v.len(),16)?;}b.add(16384)?;}for e in &self.edges{for v in [&e.id,&e.from_slot_id,&e.to_slot_id,&e.relation]{b.repeated(v.len(),16)?;}b.add(1024)?;}for r in &self.rules{for v in [&r.id,&r.tile_a_id,&r.tile_b_id]{b.repeated(v.len(),16)?;}if let Some(v)=&r.relation{b.repeated(v.len(),16)?;}b.add(1024)?;}b.finish()}
fn validate_sqlite_snapshot_subset(&self,dialect:&semio_framework_artifact_reference::ArtifactDialect,d:&SqliteDatabase,c:&mut SqliteSnapshotControl<'_>)->semio_framework_os_kernel::io_schema::IoResult<()>{c.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,0,1).map_err(semio_framework_os_kernel::io_schema::IoError::from_value_error)?;if dialect.artifact_kind!="s.wfc.wfc3d"||dialect.standard!="1"||dialect.subset!="*"{return Err(semio_framework_os_kernel::io_schema::IoError::from_value_error(invalid("wfc3d dialect differs from its owned wildcard")))}if d.table("wfc3d_document").map_err(semio_framework_os_kernel::io_schema::IoError::from_value_error)?.single_row().map_err(semio_framework_os_kernel::io_schema::IoError::from_value_error)?.text(1).map_err(semio_framework_os_kernel::io_schema::IoError::from_value_error)?!=self.schema{return Err(semio_framework_os_kernel::io_schema::IoError::from_value_error(invalid("wfc3d projected schema differs")))}c.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,1,1).map_err(semio_framework_os_kernel::io_schema::IoError::from_value_error)?;Ok(semio_framework_os_kernel::io_schema::IoOutcome::clean(()))}
}

